import { existsSync, readFileSync } from 'node:fs';
import { homedir } from 'node:os';
import { join } from 'node:path';

const NEXUS_TOKEN_KEY = '//nexus.tools.dock.tech/repository/npm-internal/:_authToken';

function readText(filePath) {
  if (!existsSync(filePath)) {
    return '';
  }

  try {
    return readFileSync(filePath, 'utf8');
  } catch {
    return '';
  }
}

function getTokenFromNpmrc(rawNpmrc) {
  const line = rawNpmrc
    .split(/\r?\n/)
    .map((entry) => entry.trim())
    .find((entry) => entry.startsWith(`${NEXUS_TOKEN_KEY}=`));

  if (!line) {
    return '';
  }

  return line.slice(line.indexOf('=') + 1).trim();
}

function isRealToken(value) {
  return value.length > 0 && !value.includes('${');
}

const envToken = (process.env.NODE_AUTH_TOKEN ?? '').trim();
const altEnvToken = (process.env.NEXUS_TOKEN ?? process.env.NPM_TOKEN ?? '').trim();
const userNpmrc = readText(join(homedir(), '.npmrc'));
const projectNpmrc = readText('.npmrc');

const userToken = getTokenFromNpmrc(userNpmrc);
const projectToken = getTokenFromNpmrc(projectNpmrc);

if (envToken || isRealToken(userToken) || isRealToken(projectToken)) {
  console.log('[publish:auth] Nexus auth detected.');
  process.exit(0);
}

console.error('[publish:auth] Missing Nexus auth for npm publish.');
console.error(`[publish:auth] Expected NODE_AUTH_TOKEN or ${NEXUS_TOKEN_KEY} in ~/.npmrc.`);
if (altEnvToken) {
  console.error('[publish:auth] Found NEXUS_TOKEN/NPM_TOKEN, but .npmrc is configured to use NODE_AUTH_TOKEN.');
  console.error('[publish:auth] Fix: map the same credential to NODE_AUTH_TOKEN in the pipeline job environment.');
}
console.error('[publish:auth] CI hint: configure the Nexus credential in Everlast/Jenkins job secrets.');
process.exit(1);